const source = $('Split In Batches').first().json;
const response = $input.first().json;
const rawContent = response.data?.content || response.body || JSON.stringify(response);
const content = String(rawContent).substring(0, 12000);
const prompt = 'Eres un especialista en normativa espanola de edificacion.
FUENTE: ' + source.name + '
CATEGORIA: ' + source.category + (source.subcategory ? ' - ' + source.subcategory : '') + '

CONTENIDO:
' + content + '

Extrae los requisitos normativos mas importantes con valores especificos.

Responde EXCLUSIVAMENTE con JSON valido:
{
  "rules": [
    {
      "title": "nombre corto",
      "content": "descripcion con valores numericos",
      "applicable_to": "tipo de obra"
    }
  ],
  "summary": "resumen en 2-3 frases"
}';
return [{ json: { prompt_system: 'Especialista en normativa edificacion espanola. Responde solo con JSON valido.', prompt_user: prompt, model: 'claude-sonnet-4-20250514', temperature: 0.1, source_id: source.id, source_name: source.name, source_url: source.url, source_type: source.source_type, category: source.category, subcategory: source.subcategory || '' }}];

const llmResponse = $input.first().json;
const prepData = $('Prepare LLM Prompt').first().json;
let content = llmResponse.content || llmResponse.response || llmResponse.text || '';
if (typeof content === 'object') content = JSON.stringify(content);
content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
let parsed = {};
try { parsed = JSON.parse(content); } catch(e) {
  const match = content.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch(e2) {} }
}
const rules = parsed.rules || [];
const summary = parsed.summary || '';
if (rules.length === 0) {
  return [{ json: { source_id: prepData.source_id, source_name: prepData.source_name, source_url: prepData.source_url, source_type: prepData.source_type, category: prepData.category, subcategory: prepData.subcategory, content: 'Sin reglas extraidas. ' + summary, rules_count: 0, summary } }];
}
return rules.map(rule => ({ json: { source_id: prepData.source_id, source_name: prepData.source_name, source_url: prepData.source_url, source_type: prepData.source_type, category: prepData.category, subcategory: prepData.subcategory, content: rule.title + ': ' + rule.content + (rule.applicable_to ? ' [Aplica a: ' + rule.applicable_to + ']' : ''), rules_count: rules.length, summary } }));

const all = $input.all();
const content = all.map(i => i.json.content || '').join('\n');
let hash = 5381;
for (let i = 0; i < content.length; i++) {
  hash = ((hash << 5) + hash) + content.charCodeAt(i);
  hash = hash & hash;
}
const newHash = Math.abs(hash).toString(16);
return all.map(item => ({ json: { ...item.json, new_hash: newHash } }));

const items = $('Compute New Hash').all();
const oldHash = $input.first().json.content_hash || '';
return items.map(item => ({ json: { ...item.json, old_hash: oldHash } }));

const all = $input.all();
const first = all[0].json;
const hasChanged = first.old_hash !== '' && first.old_hash !== first.new_hash;
const isNew = first.old_hash === '';
return [{ json: { source_id: first.source_id, source_name: first.source_name, rules_count: first.rules_count || all.length, summary: first.summary || '', new_hash: first.new_hash || '', old_hash: first.old_hash || '', has_changed: hasChanged, is_new: isNew, category: first.category || '' } }];

const all = $input.all();
const changed = all.filter(i => i.json.has_changed === true);
const newSources = all.filter(i => i.json.is_new === true);
const changedNames = changed.map(i => i.json.source_name || i.json.source_id);
const newNames = newSources.map(i => i.json.source_name || i.json.source_id);
return [{ json: { total_sources: all.length, changed_count: changed.length, new_count: newSources.length, changed_names: changedNames, new_names: newNames } }];

const data = $('Collect Changes').first().json;
const now = new Date().toLocaleString('es-ES', {timeZone: 'Europe/Madrid', dateStyle: 'long', timeStyle: 'short'});
let changeSection = '';
if (data.changed_count > 0) {
  const names = data.changed_names.map(n => '<li>' + n + '</li>').join('');
  changeSection = '<div style="background:#fdecea;border-left:4px solid #e74c3c;padding:12px 16px;margin:20px 0"><strong>⚠️ ' + data.changed_count + ' fuente(s) cambiadas:</strong><ul>' + names + '</ul><p>Los tramites de proyectos activos han sido marcados como requires_review.</p></div>';
} else {
  changeSection = '<div style="background:#d5f5e3;border-left:4px solid #27ae60;padding:12px 16px;margin:20px 0"><strong>Sin cambios detectados.</strong> Todas las fuentes son identicas a la ejecucion anterior.</div>';
}
if (data.new_count > 0) {
  const newNames = data.new_names.map(n => '<li>' + n + '</li>').join('');
  changeSection += '<div style="background:#e8f4fd;border-left:4px solid #3498db;padding:12px 16px;margin:10px 0"><strong>Nuevas fuentes indexadas (' + data.new_count + '):</strong><ul>' + newNames + '</ul></div>';
}
const body = '<html><body style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;color:#2c3e50"><h2 style="color:#2c3e50;border-bottom:2px solid #27ae60;padding-bottom:8px">Base de Conocimiento Normativa</h2><p>Actualizacion completada el <strong>' + now + '</strong>. Fuentes procesadas: <strong>' + data.total_sources + '</strong>.</p>' + changeSection + '<hr style="border:1px solid #ecf0f1;margin:20px 0"><p style="font-size:11px;color:#95a5a6">Sistema multiagente del estudio</p></body></html>';
const subjectTag = data.changed_count > 0 ? 'CAMBIOS DETECTADOS' : 'sin cambios';
const archEmail = ($('Load Architect Email').first()?.json?.value) || 'botelladesdeel98@gmail.com';
return [{ json: { subject: '[Studio AI] Normativa ' + subjectTag + ' - ' + now, html_body: body, to: archEmail } }];
